@pytest.fixture(autouse=True)
def _isolate_from_real_env(monkeypatch):
    """Keep every test away from the real .env and the Drive mount.

    The runners call load_dotenv on the project .env, which on the Mac names a
    Drive folder; a test run would then copy fixture reports to Drive (and Drive
    writes can hang). Tests that need the Drive variable set it themselves.
    """
    import sys

    noop = lambda *a, **k: None  # noqa: E731
    monkeypatch.setattr("dotenv.load_dotenv", noop)
    for name in ("run_phase0", "run_phase1", "run_phase2"):
        if name in sys.modules:
            monkeypatch.setattr(f"{name}.load_dotenv", noop)
    monkeypatch.delenv("CFB_BENCH_DRIVE_DIR", raising=False)


@pytest.fixture
def config():
    return load_config()

